import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CC9cRD7J.js";const u=JSON.parse('{"title":"Chat Interno de Staff (/sc)","description":"","frontmatter":{},"headers":[],"relativePath":"administracion/chat-de-staff.md","filePath":"administracion/chat-de-staff.md","lastUpdated":1793573363000}'),s={name:"administracion/chat-de-staff.md"};function n(r,a,d,c,l,h){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="chat-interno-de-staff-sc" tabindex="-1">Chat Interno de Staff (/sc) <a class="header-anchor" href="#chat-interno-de-staff-sc" aria-label="Permalink to &quot;Chat Interno de Staff (/sc)&quot;">​</a></h1><p>El <strong>Chat de Staff</strong> proporciona un canal privado y seguro para que los miembros del equipo se comuniquen entre sí sin que los jugadores convencionales puedan leer sus mensajes.</p><hr><h2 id="💬-formas-de-comunicacion" tabindex="-1">💬 Formas de Comunicación <a class="header-anchor" href="#💬-formas-de-comunicacion" aria-label="Permalink to &quot;💬 Formas de Comunicación&quot;">​</a></h2><h3 id="_1-comando-directo" tabindex="-1">1. Comando Directo <a class="header-anchor" href="#_1-comando-directo" aria-label="Permalink to &quot;1. Comando Directo&quot;">​</a></h3><ul><li><strong>Enviar un mensaje al chat interno:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/sc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mensaj</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><em>(Permiso requerido: <code>staff.staffchat</code>)</em></li></ul><h3 id="_2-alternar-modo-de-chat" tabindex="-1">2. Alternar Modo de Chat <a class="header-anchor" href="#_2-alternar-modo-de-chat" aria-label="Permalink to &quot;2. Alternar Modo de Chat&quot;">​</a></h3><ul><li>Si ejecutas <code>/sc</code> sin argumentos, alternas tu modo de chat: a partir de ese momento, todo lo que escribas normalmente se enviará directamente al canal del staff sin necesidad de volver a escribir el comando.</li></ul><h3 id="_3-prefijo-rapido-handle" tabindex="-1">3. Prefijo Rápido (Handle <code>@</code>) <a class="header-anchor" href="#_3-prefijo-rapido-handle" aria-label="Permalink to &quot;3. Prefijo Rápido (Handle `@`)&quot;">​</a></h3><p>En <code>config.yml</code> se puede configurar un carácter de acceso rápido (por defecto <code>@</code>).</p><ul><li>Si escribes en el chat normal empezando por <code>@</code>:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@chicos, vengan a revisar a este usuario en el spawn</span></span></code></pre></div></li><li>El plugin detectará el prefijo y redirigirá el mensaje automáticamente al chat de staff, suprimiendo la difusión pública.</li></ul>',11)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
